// Generated by OrchestKit Claude Plugin
// Created: 2026-05-22

/**
 * Session Registrar — SessionStart hook (M168 Phase 2, #1912)
 *
 * Registers this Claude Code session in the shared SQLite session DB
 * (~/.local/state/orchestkit/sessions.db). Runs sweeps on the way in:
 *
 *   1. Mark rows where last_heartbeat < now - 86400 AND status='running'
 *      as status='crashed' (24h liveness window — matches the agent-watchdog
 *      cap from #1882).
 *   2. Delete expired locks (expires_at < now).
 *
 * The INSERT uses OR REPLACE so re-entering an existing sid (e.g. CC resume)
 * just refreshes the row — never blocks the session.
 *
 * Layer 1 of the 4-layer coordination architecture (#1908). Replaces the
 * broken agent-watchdog liveness semantics from #1830.
 *
 * Hook event: SessionStart (async, timeout: 5s).
 */

import type { HookInput, HookResult, HookContext } from '../types.js';
import { outputSilentSuccess, outputSessionStartContext } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';
import { writeWithRetry } from '../lib/session-registry.js';
import { execSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HOOK_NAME = 'lifecycle/session-registrar';
const SECONDS_PER_DAY = 86_400;

/**
 * Fallback liveness window for peers with no recorded messaging socket (#2242).
 * Only reached for rows written before #3318 or by a CC that exports no socket
 * — for everything else the socket file is the liveness signal (see
 * isPeerLive). Kept because such a peer still thrashes the working tree, so
 * dropping it from the warning would trade a wrong pid for a missing warning.
 */
const PEER_LIVENESS_WINDOW = 300;

/**
 * sessions.pid when no addressable Claude Code pid is available (#3318).
 *
 * Deliberately NOT process.pid. Hooks run as a short-lived `node run-hook.mjs`
 * child that exits before anything reads the row, so recording it produced a
 * pid that always looked plausible and was never reachable. 0 cannot be
 * mistaken for a real process, and formatPeerWarning renders it as "unknown".
 */
const PID_UNKNOWN = 0;

/** One concurrent session sharing this repo + branch + main working tree. */
interface PeerRow {
  sid: string;
  /** The peer's Claude Code pid, or PID_UNKNOWN when it recorded none. */
  pid: number;
  /** The peer's CC messaging socket, or null when it is not reachable that way. */
  messagingSocket: string | null;
}

/**
 * Resolve the git top-level for the given cwd. Returns cwd itself if not
 * inside a repo. Errors are swallowed — registration never blocks CC.
 */
function getRepoPath(cwd: string): string {
  try {
    const out = execSync('git rev-parse --show-toplevel', {
      cwd,
      stdio: ['ignore', 'pipe', 'ignore'],
      encoding: 'utf8',
      timeout: 1500,
    }).trim();
    return out || cwd;
  } catch {
    return cwd;
  }
}

/** SHA-256 of the repo path — stable identifier across worktrees + reboots. */
function hashRepo(repoPath: string): string {
  return createHash('sha256').update(repoPath).digest('hex').slice(0, 16);
}

/** Resolve the current git branch for cwd. Returns null when not in a repo. */
function getBranch(cwd: string): string | null {
  try {
    const out = execSync('git rev-parse --abbrev-ref HEAD', {
      cwd,
      stdio: ['ignore', 'pipe', 'ignore'],
      encoding: 'utf8',
      timeout: 1500,
    }).trim();
    return out || null;
  } catch {
    return null;
  }
}

/**
 * Resolve the worktree path for the given cwd. Detached worktrees write
 * their .git as a file (gitdir pointer); cwd will be the worktree path
 * unless we are inside a subdir. We resolve via `git rev-parse --git-dir`
 * — for worktrees this points at <main>/.git/worktrees/<name> — and we
 * read the gitdir's `gitdir` file to find the worktree root.
 */
function getWorktreePath(cwd: string, repoPath: string): string | null {
  try {
    const out = execSync('git rev-parse --git-common-dir', {
      cwd,
      stdio: ['ignore', 'pipe', 'ignore'],
      encoding: 'utf8',
      timeout: 1500,
    }).trim();
    // If common-dir == git-dir, we're in the main worktree.
    const gitDir = execSync('git rev-parse --git-dir', {
      cwd,
      stdio: ['ignore', 'pipe', 'ignore'],
      encoding: 'utf8',
      timeout: 1500,
    }).trim();
    if (gitDir === out) return null;
    // For linked worktrees, git rev-parse --show-toplevel returns the worktree path.
    return repoPath;
  } catch {
    return null;
  }
}

/** Best-effort read of the OrchestKit package version. */
function getOrkVersion(): string | null {
  try {
    const __filename = fileURLToPath(import.meta.url);
    // Walk up from src/hooks/dist/lifecycle/... to find the nearest package.json
    // with name "@orchestkit/hooks" or skip if we can't find it.
    const here = __filename;
    // Hooks ship as bundled .mjs — package.json sits next to dist/.
    // Conservative: just return null when not resolvable.
    const pkgPath = join(here, '..', '..', '..', 'package.json');
    const raw = readFileSync(pkgPath, 'utf8');
    const j = JSON.parse(raw) as { version?: string };
    return j.version ?? null;
  } catch {
    return null;
  }
}

/** Best-effort read of the Claude Code version from env. */
function getCcVersion(): string | null {
  return process.env.CLAUDE_CODE_VERSION || process.env.CC_VERSION || null;
}

/**
 * Resolve the pid of the Claude Code process that owns this hook (#3318).
 *
 * CC exports CLAUDE_PID and the hook child inherits it. There is deliberately
 * no process.ppid fallback: whether the parent is CC or a shell it spawned
 * depends on how CC invokes the hook, so ppid is another unverifiable guess of
 * exactly the kind this function exists to remove. Unknown stays unknown.
 */
function getCcPid(): number {
  const raw = process.env.CLAUDE_PID;
  if (!raw) return PID_UNKNOWN;
  const parsed = Number.parseInt(raw, 10);
  return Number.isInteger(parsed) && parsed > 0 ? parsed : PID_UNKNOWN;
}

/**
 * The peer-messaging socket CC exports for this session, verbatim (#3318).
 * Stored as-is and never reconstructed from a pid — the path shape is CC's
 * contract, not ours.
 */
function getMessagingSocket(): string | null {
  return process.env.CLAUDE_CODE_MESSAGING_SOCKET || null;
}

/**
 * Sweep stale sessions + expired locks. Runs inside the hook's write
 * transaction. Pure SQL — no JS allocation per row.
 */
function sweep(db: import('node:sqlite').DatabaseSync, nowSec: number): void {
  const cutoff = nowSec - SECONDS_PER_DAY;
  db.prepare(
    `UPDATE sessions SET status = 'crashed'
     WHERE last_heartbeat < ? AND status = 'running'`,
  ).run(cutoff);
  db.prepare('DELETE FROM locks WHERE expires_at < ?').run(nowSec);
}

/**
 * Insert (or replace) the session row for this Claude Code process.
 * Idempotent on sid: re-running just refreshes started_at + heartbeat.
 */
function register(
  db: import('node:sqlite').DatabaseSync,
  row: {
    sid: string;
    pid: number;
    cwd: string;
    repo_hash: string;
    repo_path: string;
    worktree_path: string | null;
    branch: string | null;
    now: number;
    cc_version: string | null;
    ork_version: string | null;
    messaging_socket: string | null;
  },
): void {
  db.prepare(
    `INSERT INTO sessions (
       sid, pid, cwd, repo_hash, repo_path, worktree_path, branch,
       status, started_at, last_heartbeat, cc_version, ork_version,
       messaging_socket
     ) VALUES (
       @sid, @pid, @cwd, @repo_hash, @repo_path, @worktree_path, @branch,
       'running', @now, @now, @cc_version, @ork_version,
       @messaging_socket
     )
     ON CONFLICT(sid) DO UPDATE SET
       pid              = excluded.pid,
       cwd              = excluded.cwd,
       repo_hash        = excluded.repo_hash,
       repo_path        = excluded.repo_path,
       worktree_path    = excluded.worktree_path,
       branch           = excluded.branch,
       status           = 'running',
       last_heartbeat   = excluded.last_heartbeat,
       cc_version       = excluded.cc_version,
       ork_version      = excluded.ork_version,
       messaging_socket = excluded.messaging_socket`,
  ).run(row);
}

/**
 * Is this peer row still a live session? (#3318)
 *
 * A recorded messaging socket is the authoritative signal: CC creates the
 * socket file for the session's lifetime, so its presence answers "is that
 * session still there" directly instead of inferring it from how recently the
 * peer happened to run a tool. That matters because last_heartbeat only moves
 * on PostToolUse — an alive-but-idle session (waiting on the operator) goes
 * heartbeat-stale in 5 minutes and used to vanish from the warning.
 *
 * Rows with no socket keep the heartbeat window as the fallback bound.
 *
 * Known residue: a SIGKILLed CC leaves its socket file behind, so such a peer
 * reads as live until the 24h status sweep reaps the row. That is a strictly
 * smaller error than the status quo, where the identifier was wrong 100% of
 * the time, and it is bounded by an existing mechanism.
 */
function isPeerLive(
  row: { messaging_socket: string | null; last_heartbeat: number },
  nowSec: number,
): boolean {
  if (row.messaging_socket) return existsSync(row.messaging_socket);
  return row.last_heartbeat > nowSec - PEER_LIVENESS_WINDOW;
}

/**
 * Find live peer sessions that share this repo + branch AND sit in the same
 * (main) working tree — the ONLY configuration that thrashes: branch flips
 * mid-operation, node_modules rewrites, pre-push failures on stale state.
 *
 * Returns [] for the safe cases (no branch, or this session is worktree-isolated)
 * without touching the DB, so worktree/different-branch sessions never warn.
 */
function findPeers(
  db: import('node:sqlite').DatabaseSync,
  args: {
    sid: string;
    repoHash: string;
    branch: string | null;
    worktreePath: string | null;
    nowSec: number;
  },
): PeerRow[] {
  if (!args.branch || args.worktreePath !== null) return [];
  // Liveness is decided per-row in isPeerLive, not by a SQL heartbeat bound:
  // the socket test needs a filesystem stat, which SQL cannot do.
  const rows = db
    .prepare(
      `SELECT sid, pid, messaging_socket, last_heartbeat FROM sessions
       WHERE status = 'running' AND repo_hash = ? AND branch = ?
         AND worktree_path IS NULL AND sid != ?`,
    )
    .all(args.repoHash, args.branch, args.sid) as Array<Record<string, unknown>>;
  return rows
    .map(r => ({
      sid: String(r.sid),
      pid: Number(r.pid),
      messaging_socket: r.messaging_socket == null ? null : String(r.messaging_socket),
      last_heartbeat: Number(r.last_heartbeat),
    }))
    .filter(r => isPeerLive(r, args.nowSec))
    .map(r => ({ sid: r.sid, pid: r.pid, messagingSocket: r.messaging_socket }));
}

/** Render one peer's identity — never a pid the operator cannot look up. */
function describePeer(p: PeerRow): string {
  const pid = p.pid > PID_UNKNOWN ? `pid ${p.pid}` : 'pid unknown';
  const reach = p.messagingSocket ? '' : ', no messaging socket';
  return `  - session ${p.sid.slice(0, 8)} (${pid}${reach})`;
}

/** Build the worktree-recommendation warning injected as SessionStart context. */
function formatPeerWarning(
  peers: PeerRow[],
  repoPath: string,
  branch: string,
): string {
  const repoName = repoPath.split('/').filter(Boolean).pop() || 'repo';
  const list = peers.map(describePeer).join('\n');
  return [
    `WARNING: ${peers.length} other Claude Code session(s) running in this repo on branch '${branch}', sharing the same working tree:`,
    list,
    '',
    'Concurrent sessions on one working tree thrash each other: branch flips mid-operation, node_modules rewrites, pre-push failures on stale state.',
    'Isolate this session in a git worktree before mutating working-tree state:',
    `  WT=$(~/.claude/hooks/worktree-new.sh ${repoName}-task ${branch}-2) && cd "$WT"`,
  ].join('\n');
}

export function sessionRegistrar(
  input: HookInput,
  ctx: HookContext = NOOP_CTX,
): HookResult {
  const sid = input.session_id;
  if (!sid) return outputSilentSuccess();

  const cwd = input.project_dir || process.cwd();
  const repoPath = getRepoPath(cwd);
  const repoHash = hashRepo(repoPath);
  const worktreePath = getWorktreePath(cwd, repoPath);
  const branch = getBranch(cwd);
  const nowSec = Math.floor(Date.now() / 1000);
  const ccVersion = getCcVersion();
  const orkVersion = getOrkVersion();

  let peers: PeerRow[] = [];
  try {
    peers = writeWithRetry(db => {
      sweep(db, nowSec);
      register(db, {
        sid,
        // #3318: the CC process, NOT process.pid (the hook child, already gone).
        pid: getCcPid(),
        messaging_socket: getMessagingSocket(),
        cwd,
        repo_hash: repoHash,
        repo_path: repoPath,
        worktree_path: worktreePath,
        branch,
        now: nowSec,
        cc_version: ccVersion,
        ork_version: orkVersion,
      });
      // Peer-collision detection (#2242) runs in the same txn so it observes the
      // just-swept state. Self-excluded via sid; safe cases return [] (no query).
      return findPeers(db, { sid, repoHash, branch, worktreePath, nowSec });
    });
  } catch (err) {
    ctx.log(HOOK_NAME, `register failed: ${(err as Error).message}`);
  }

  if (peers.length > 0 && branch) {
    return outputSessionStartContext(formatPeerWarning(peers, repoPath, branch));
  }
  return outputSilentSuccess();
}

/** Exposed for tests. */
export const __internals = {
  hashRepo,
  sweep,
  register,
  getRepoPath,
  getCcPid,
  isPeerLive,
  findPeers,
  formatPeerWarning,
};
